package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.BackHandler
import androidx.activity.compose.setContent
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.filled.Add
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.runtime.saveable.rememberSaveable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import java.time.LocalDate
import java.time.format.DateTimeParseException

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    // ponytail: DB access on main thread; fine for a few patients, move to Dispatchers.IO if it grows.
    val db = Db(applicationContext)
    setContent { MaterialTheme { App(db) } }
  }
}

@Composable
fun App(db: Db) {
  var patientId by rememberSaveable { mutableStateOf<Long?>(null) }
  var adding by rememberSaveable { mutableStateOf(false) }
  val patient = patientId?.let { id -> db.patients().find { it.id == id } }
  when {
    patient == null -> RegisterScreen(db.patients()) { patientId = it.id }
    adding -> {
      BackHandler { adding = false }
      VisitForm(patient, onCancel = { adding = false }) { db.addVisit(patient.id, it); adding = false }
    }
    else -> {
      BackHandler { patientId = null }
      DetailScreen(patient, db.visits(patient.id), onBack = { patientId = null }, onAdd = { adding = true })
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun Screen(title: String, onBack: (() -> Unit)? = null, fab: @Composable () -> Unit = {}, content: @Composable (PaddingValues) -> Unit) {
  Scaffold(
    topBar = {
      TopAppBar(title = { Text(title) }, navigationIcon = {
        if (onBack != null) IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back") }
      })
    },
    floatingActionButton = fab,
    content = content,
  )
}

@Composable
fun RegisterScreen(patients: List<Patient>, onOpen: (Patient) -> Unit) {
  val today = LocalDate.now()
  Screen("ANC Register") { pad ->
    LazyColumn(Modifier.padding(pad)) {
      items(patients) { p ->
        ListItem(
          headlineContent = { Text(p.name) },
          supportingContent = { Text("Age ${ageOn(p.dob, today)} · Due ${p.edd}") },
          trailingContent = { Text("${gaWeeksOn(p.edd, today)} wks", style = MaterialTheme.typography.titleMedium) },
          modifier = Modifier.clickable { onOpen(p) },
        )
        HorizontalDivider()
      }
    }
  }
}

@Composable
fun DetailScreen(p: Patient, visits: List<Visit>, onBack: () -> Unit, onAdd: () -> Unit) {
  val today = LocalDate.now()
  Screen(p.name, onBack, fab = {
    ExtendedFloatingActionButton(onClick = onAdd, icon = { Icon(Icons.Filled.Add, null) }, text = { Text("Record visit") })
  }) { pad ->
    LazyColumn(Modifier.padding(pad), contentPadding = PaddingValues(16.dp, 8.dp, 16.dp, 96.dp)) {
      item {
        Text("Age ${ageOn(p.dob, today)} · Due ${p.edd} · ${gaWeeksOn(p.edd, today)} weeks")
        Text("ANC visits", style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 16.dp, bottom = 8.dp))
        if (visits.isEmpty()) Text("No visits recorded.")
      }
      items(visits) { v ->
        Card(Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
          Column(Modifier.padding(12.dp)) {
            Text("${v.date} · ${v.gaWeeks} wks", style = MaterialTheme.typography.titleSmall)
            Text("Weight ${v.weightKg} kg · BP ${v.systolic}/${v.diastolic} mmHg" + (v.hb?.let { " · Hb $it g/dL" } ?: ""))
            if (v.dangerSigns.isNotEmpty()) Text("Danger signs: ${v.dangerSigns.joinToString()}", color = MaterialTheme.colorScheme.error)
            if (v.notes.isNotBlank()) Text(v.notes)
          }
        }
      }
    }
  }
}

@Composable
fun VisitForm(p: Patient, onCancel: () -> Unit, onSave: (Visit) -> Unit) {
  var date by rememberSaveable { mutableStateOf(LocalDate.now().toString()) }
  var ga by rememberSaveable { mutableStateOf(gaWeeksOn(p.edd, LocalDate.now()).toString()) }
  var weight by rememberSaveable { mutableStateOf("") }
  var sys by rememberSaveable { mutableStateOf("") }
  var dia by rememberSaveable { mutableStateOf("") }
  var signs by rememberSaveable { mutableStateOf(listOf<String>()) }
  var notes by rememberSaveable { mutableStateOf("") }
  var error by remember { mutableStateOf<String?>(null) }

  fun validate(): Visit? {
    val d = try { LocalDate.parse(date.trim()) } catch (_: DateTimeParseException) { return null.also { error = "Visit date must be YYYY-MM-DD" } }
    if (d.isAfter(LocalDate.now())) return null.also { error = "Visit date cannot be in the future" }
    val g = ga.trim().toIntOrNull()?.takeIf { it in 1..45 } ?: return null.also { error = "Gestational age must be 1–45 weeks" }
    val w = weight.trim().toDoubleOrNull()?.takeIf { it in 20.0..250.0 } ?: return null.also { error = "Weight must be 20–250 kg" }
    val s = sys.trim().toIntOrNull()?.takeIf { it in 50..300 } ?: return null.also { error = "Systolic must be 50–300 mmHg" }
    val di = dia.trim().toIntOrNull()?.takeIf { it in 30..200 } ?: return null.also { error = "Diastolic must be 30–200 mmHg" }
    if (di >= s) return null.also { error = "Diastolic must be lower than systolic" }
    return Visit(d, g, w, s, di, null, signs, notes.trim())
  }

  Screen("New visit · ${p.name}", onCancel) { pad ->
    Column(Modifier.padding(pad).padding(16.dp).verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(8.dp)) {
      val num = KeyboardOptions(keyboardType = KeyboardType.Number)
      val dec = KeyboardOptions(keyboardType = KeyboardType.Decimal)
      OutlinedTextField(date, { date = it }, label = { Text("Visit date (YYYY-MM-DD)") }, singleLine = true, modifier = Modifier.fillMaxWidth())
      OutlinedTextField(ga, { ga = it }, label = { Text("Gestational age (weeks)") }, singleLine = true, keyboardOptions = num, modifier = Modifier.fillMaxWidth())
      OutlinedTextField(weight, { weight = it }, label = { Text("Weight (kg)") }, singleLine = true, keyboardOptions = dec, modifier = Modifier.fillMaxWidth())
      Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
        OutlinedTextField(sys, { sys = it }, label = { Text("Systolic (mmHg)") }, singleLine = true, keyboardOptions = num, modifier = Modifier.weight(1f))
        OutlinedTextField(dia, { dia = it }, label = { Text("Diastolic (mmHg)") }, singleLine = true, keyboardOptions = num, modifier = Modifier.weight(1f))
      }
      Text("Danger signs", style = MaterialTheme.typography.titleSmall, modifier = Modifier.padding(top = 8.dp))
      CheckRow("None", signs.isEmpty()) { signs = emptyList() }
      DANGER_SIGNS.forEach { s -> CheckRow(s, s in signs) { signs = if (s in signs) signs - s else signs + s } }
      OutlinedTextField(notes, { notes = it }, label = { Text("Notes") }, minLines = 3, modifier = Modifier.fillMaxWidth())
      error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
      Button(onClick = { validate()?.let(onSave) }, modifier = Modifier.fillMaxWidth()) { Text("Save visit") }
    }
  }
}

@Composable
fun CheckRow(label: String, checked: Boolean, onToggle: () -> Unit) {
  Row(Modifier.fillMaxWidth().clickable(onClick = onToggle), verticalAlignment = Alignment.CenterVertically) {
    Checkbox(checked, { onToggle() })
    Text(label)
  }
}
